    fn pop_front(&mut self) -> (v: V)
        requires
            old(self).wf(),
            old(self)@.len() > 0,
        ensures
            self.wf(),
            self@ == old(self)@.subrange(1, old(self)@.len() as int),
            v == old(self)@[0],
