{
    let new_bucket = set_two_bit_exec(bucket, 2 * i, high, low);
    assert(color_view(high, low) == color_view(
        get_bit!(new_bucket, add(mul(2, i), 1)),
        get_bit!(new_bucket, mul(2, i)),
