pub proof fn ex7_rev_involutive(xs: NatList)
    ensures xs.reverse().reverse() =~= xs
{
    // Prove by extensional equality (same length, same indexing).
    assert(xs.reverse().len() == xs.len());
    assert(xs.reverse().reverse().len() == xs.len());

