        assert(xs.reverse()[xs.len() - 1 - i] == xs[xs.len() - 1 - (xs.len() - 1 - i)]);
        assert(xs.len() - 1 - (xs.len() - 1 - i) == i);
    };

    assert(xs.reverse().reverse() =~= xs);
}

