    requires rt_inv(e)
    ensures rt_lhs(e) <= rt_rhs(e)
    decreases e
{
    match e {
        RtStep1::Refl { x: _ } => {
        }
        RtStep1::Snoc { prev, y } => {
            let p = *prev;
            lemma_rt_implies_le(p);
            // rt_inv(e) implies step1(rt_rhs(p), y), hence y = rt_rhs(p) + 1.
            assert(step1(rt_rhs(p), y));
            assert(rt_rhs(p) < y);
            // Combine: rt_lhs(p) <= rt_rhs(p) < y, and rt_lhs(e)=rt_lhs(p), rt_rhs(e)=y.
            assert(rt_lhs(p) <= y);
        }
    }
}

