        lemma_rt_refl(x)
    } else {
        // From x <= y and x != y we get x < y, so y > 0 and x <= y-1.
        assert(x < y);
        assert(y > 0);
        let y1 = (y - 1) as nat;
        assert(x <= y1);

        let prev = lemma_le_implies_rt(x, y1);
        // Extend by a final successor step from y-1 to y.
        assert(step1(y1, y));
        lemma_rt_snoc(prev, y)
    }
}

} // verus!
